function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // river
  ctx.beginPath();
  ctx.moveTo(0, H/2 + 50 * Math.sin(t));
  for (let x = 0; x < W; x++) {
    ctx.lineTo(x, H/2 + 50 * Math.sin(t + x/50));
  }
  ctx.lineTo(W, H);
  ctx.lineTo(0, H);
  ctx.closePath();
  ctx.stroke();
  // lotus
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  // stick figure on lotus
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 20 * Math.sin(t) - 30, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 * Math.sin(t) - 20);
  ctx.lineTo(W/2, H/2 + 20 * Math.sin(t) + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 * Math.sin(t) - 10);
  ctx.lineTo(W/2 - 10, H/2 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 * Math.sin(t) - 10);
  ctx.lineTo(W/2 + 10, H/2 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.restore();
}
